using System.Data;using System.Data.Common;using System.Globalization;using System.Text.Json;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Storage;using Qms.Application.ElectronicSignatures;using Qms.Application.MasterBatchRecords;using Qms.Application.Security;using Qms.Contracts.Common;using Qms.Contracts.MasterBatchRecords;using Qms.Domain.AuditTrail;using Qms.Domain.ElectronicSignatures;using Qms.Domain.MasterBatchRecords;using Qms.Domain.Notifications;using Qms.Domain.QualityRecords;using Qms.Domain.Workflows;using Qms.Infrastructure.Persistence;
namespace Qms.Infrastructure.MasterBatchRecords;public sealed class MbrService(QmsDbContext db,TimeProvider time,ICurrentUser user,IElectronicSignatureService signatures):IMbrService
{
 public async Task<MbrOptionsResponse>GetOptionsAsync(CancellationToken ct){var people=await(from u in db.Users.AsNoTracking()join d in db.Departments.AsNoTracking()on u.DepartmentId equals d.Id into ds from d in ds.DefaultIfEmpty()where u.IsActive orderby u.DisplayName select new MbrIdentityOption(u.Id,u.DisplayName,d==null?null:d.Name)).ToListAsync(ct);var defs=await db.MbrLookupDefinitions.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.SortOrder).ToListAsync(ct);IReadOnlyList<MbrCodeOption>Of(string c)=>defs.Where(x=>x.Category==c).Select(x=>new MbrCodeOption(x.Code,x.Name)).ToList();return new(people,Of("Product"),Of("DosageForm"),Of("BatchUnit"),Of("Site"),Of("Line"),Of("Phase"),Of("ParameterUnit"));}public async Task<IReadOnlyList<MbrLookupResponse>>ListLookupsAsync(CancellationToken ct)=>await db.MbrLookupDefinitions.AsNoTracking().OrderBy(x=>x.Category).ThenBy(x=>x.SortOrder).Select(x=>new MbrLookupResponse(x.Id,x.Category,x.Code,x.Name,x.SortOrder,x.IsActive)).ToListAsync(ct);public async Task<MbrLookupResponse>CreateLookupAsync(CreateMbrLookupRequest r,CancellationToken ct){if(await db.MbrLookupDefinitions.AnyAsync(x=>x.Category==r.Category.Trim()&&x.Code==r.Code.Trim(),ct))throw new InvalidOperationException("Aynı M.12 lookup kodu mevcut.");var now=time.GetUtcNow();var x=MbrLookupDefinition.Create(r.Category,r.Code,r.Name,r.SortOrder,now);db.Add(x);db.Add(Event("MbrLookupDefinition",x.Id,1,"MbrLookupCreated",now,new{x.Category,x.Code,x.Name}));await db.SaveChangesAsync(ct);return new(x.Id,x.Category,x.Code,x.Name,x.SortOrder,x.IsActive);}public async Task<MbrLookupResponse?>UpdateLookupAsync(Guid id,UpdateMbrLookupRequest r,CancellationToken ct){var x=await db.MbrLookupDefinitions.SingleOrDefaultAsync(x=>x.Id==id,ct);if(x is null)return null;var now=time.GetUtcNow();x.Update(r.Name,r.SortOrder,r.IsActive,now);db.Add(Event("MbrLookupDefinition",x.Id,1,"MbrLookupUpdated",now,new{x.Category,x.Code,x.Name,x.IsActive}));await db.SaveChangesAsync(ct);return new(x.Id,x.Category,x.Code,x.Name,x.SortOrder,x.IsActive);}
 public async Task<PagedResponse<MbrListItemResponse>>SearchAsync(MbrSearchRequest r,CancellationToken ct){if(r.Page<1||r.PageSize is not(10 or 25 or 50 or 100))throw new ArgumentException("Sayfa geçersizdir.");var q=from x in db.MasterBatchRecords.AsNoTracking()join qr in db.QualityRecords.AsNoTracking()on x.QualityRecordId equals qr.Id select new Row{Mbr=x,Number=qr.RecordNumber};foreach(var f in r.Filters??[]){var v=f.Value?.Trim()??"";q=f.Field.Trim().ToLowerInvariant()switch{"recordnumber"=>q.Where(x=>x.Number.ToLower().Contains(v.ToLower())),"product"=>q.Where(x=>x.Mbr.ProductName.ToLower().Contains(v.ToLower())),"site"=>q.Where(x=>x.Mbr.SiteCode==v),"status"=>Enum.TryParse<MasterBatchRecordStatus>(v,true,out var s)?q.Where(x=>x.Mbr.Status==s):throw new ArgumentException("Durum geçersizdir."),_=>throw new ArgumentException("Filtre kolonu geçersizdir.")};}var total=await q.LongCountAsync(ct);var desc=r.SortDirection.Equals("desc",StringComparison.OrdinalIgnoreCase);q=desc?q.OrderByDescending(x=>x.Mbr.CreatedAtUtc):q.OrderBy(x=>x.Mbr.CreatedAtUtc);var items=await q.Skip((r.Page-1)*r.PageSize).Take(r.PageSize).Select(x=>new MbrListItemResponse(x.Mbr.Id,x.Number,x.Mbr.ProductCode,x.Mbr.ProductName,x.Mbr.DocumentVersion,x.Mbr.SiteName,x.Mbr.LineName,x.Mbr.Author,x.Mbr.Status.ToString(),x.Mbr.CreatedAtUtc,x.Mbr.Version)).ToListAsync(ct);return new(items,r.Page,r.PageSize,total,total==0?0:(int)Math.Ceiling(total/(double)r.PageSize));}
 public async Task<MbrDetailsResponse?>GetDetailsAsync(Guid id,CancellationToken ct){var x=await db.MasterBatchRecords.AsNoTracking().Include(x=>x.Steps).SingleOrDefaultAsync(x=>x.Id==id,ct);if(x is null)return null;var qr=await db.QualityRecords.AsNoTracking().SingleAsync(q=>q.Id==x.QualityRecordId,ct);var ev=await db.AuditEvents.AsNoTracking().Where(e=>e.AggregateType=="MasterBatchRecord"&&e.AggregateId==id).OrderByDescending(e=>e.OccurredAtUtc).ToListAsync(ct);var sig=await db.ElectronicSignatures.AsNoTracking().Where(s=>s.QualityRecordId==x.QualityRecordId).OrderByDescending(s=>s.SignedAtUtc).ToListAsync(ct);var ts=new List<MbrTransitionResponse>();foreach(var t in Transitions(x.Status))if(await CanAct(id,Role(t.Code),ct))ts.Add(t);var record=new MbrRecordResponse(x.Id,x.QualityRecordId,x.PreviousVersionId,qr.RecordNumber,x.ProductCode,x.ProductName,x.DosageFormCode,x.DosageFormName,x.Strength,x.BatchSize,x.BatchUnitCode,x.BatchUnitName,x.SiteCode,x.SiteName,x.LineCode,x.LineName,x.DocumentVersion,x.ChangeReason,x.AuthorUserId,x.Author,x.ReviewerUserId,x.Reviewer,x.ApproverUserId,x.Approver,x.EffectiveAtUtc,x.Status.ToString(),x.CreatedAtUtc,x.UpdatedAtUtc,x.Version);return new(record,x.Steps.OrderBy(s=>s.Order).Select(s=>new MbrStepResponse(s.Id,s.Order,s.PhaseCode,s.PhaseName,s.Instruction,s.MaterialOrEquipmentReference,s.IsCritical,s.Parameter,s.LowerLimit,s.UpperLimit,s.UnitCode,s.UnitName)).ToList(),ev.Select(e=>new MbrEventResponse(e.Id,e.AggregateVersion,e.EventType,e.ActorDisplayNameSnapshot,e.OccurredAtUtc,e.Reason,e.Payload.RootElement.Clone())).ToList(),sig.Select(s=>new MbrSignatureResponse(s.Id,s.RecordVersion,s.SignerDisplayNameSnapshot,s.Meaning,s.SignedAtUtc,s.ContentHash,s.Comment)).ToList(),ts);}
 public async Task<MbrDetailsResponse>CreateAsync(CreateMbrRequest r,CancellationToken ct){if(!user.DepartmentId.HasValue)throw new InvalidOperationException("MBR oluşturan kullanıcının bölümü olmalıdır.");var author=await Resolve(r.AuthorUserId,"Yazar",ct);var reviewer=await Resolve(r.ReviewerUserId,"İnceleyen",ct);var approver=await Resolve(r.ApproverUserId,"Onaylayan",ct);if(author.Id!=user.Id&&!user.IsInRole(QmsRoles.Administrator)&&!user.IsInRole(QmsRoles.QualityAssurance))throw new QmsForbiddenException("MBR kaydını yalnız seçilen yazar veya kalite yöneticisi oluşturabilir.");MasterBatchRecord?previous=null;if(r.PreviousVersionId.HasValue){previous=await db.MasterBatchRecords.Include(x=>x.Steps).SingleOrDefaultAsync(x=>x.Id==r.PreviousVersionId,ct)??throw new ArgumentException("Önceki MBR bulunamadı.");if(previous.Status!=MasterBatchRecordStatus.Effective)throw new InvalidOperationException("Yalnız yürürlükteki MBR üzerinden yeni revizyon açılabilir.");}var product=previous is null?await Lookup("Product",r.ProductCode,ct):(previous.ProductCode,previous.ProductName);var form=previous is null?await Lookup("DosageForm",r.DosageFormCode,ct):(previous.DosageFormCode,previous.DosageFormName);var unit=previous is null?await Lookup("BatchUnit",r.BatchUnitCode,ct):(previous.BatchUnitCode,previous.BatchUnitName);var site=previous is null?await Lookup("Site",r.SiteCode,ct):(previous.SiteCode,previous.SiteName);var line=previous is null?await Lookup("Line",r.LineCode,ct):(previous.LineCode,previous.LineName);var now=time.GetUtcNow();await using var tx=await db.Database.BeginTransactionAsync(ct);var no=$"MBR-{now.Year}-{await Next("mbr",now.Year,tx,ct):000000}";var qr=QualityRecord.Create(no,"M.12",user.Id,user.DepartmentId.Value,now);qr.Submit(now);var x=MasterBatchRecord.Create(qr.Id,previous?.Id,product.Item1,product.Item2,form.Item1,form.Item2,previous?.Strength??r.Strength,previous?.BatchSize??r.BatchSize,unit.Item1,unit.Item2,site.Item1,site.Item2,line.Item1,line.Item2,r.DocumentVersion,r.ChangeReason,author.Id,author.Name,reviewer.Id,reviewer.Name,approver.Id,approver.Name,now);db.Add(qr);db.Add(x);if(previous is not null)foreach(var s in previous.Steps.OrderBy(s=>s.Order)){var step=MasterBatchStep.Create(x.Id,s.Order,s.PhaseCode,s.PhaseName,s.Instruction,s.MaterialOrEquipmentReference,s.IsCritical,s.Parameter,s.LowerLimit,s.UpperLimit,s.UnitCode,s.UnitName);x.AddStep(x.Version,step,now);db.Add(step);}await Assign(x.Id,WorkflowTaskRoles.MbrAuthor,author.Id,now,ct);await Assign(x.Id,WorkflowTaskRoles.MbrReviewer,reviewer.Id,now,ct);await Assign(x.Id,WorkflowTaskRoles.MbrApprover,approver.Id,now,ct);db.Add(Audit(x,"MbrCreated",now,new{no,previousVersionId=previous?.Id,x.DocumentVersion}));await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return(await GetDetailsAsync(x.Id,ct))!;}
 public async Task<MbrDetailsResponse?>AddStepAsync(Guid id,AddMbrStepRequest r,CancellationToken ct){await EnsureActor(id,WorkflowTaskRoles.MbrAuthor,ct);var x=await Load(id,ct);if(x is null)return null;var phase=await Lookup("Phase",r.PhaseCode,ct);(string,string)?unit=null;if(!string.IsNullOrWhiteSpace(r.UnitCode))unit=await Lookup("ParameterUnit",r.UnitCode,ct);var now=time.GetUtcNow();var step=MasterBatchStep.Create(id,r.Order,phase.Item1,phase.Item2,r.Instruction,r.MaterialOrEquipmentReference,r.IsCritical,r.Parameter,r.LowerLimit,r.UpperLimit,unit?.Item1,unit?.Item2);x.AddStep(r.ExpectedVersion,step,now);db.Add(step);db.Add(Audit(x,"MbrStepAdded",now,new{step.Id,step.Order,step.PhaseCode,step.IsCritical}));await db.SaveChangesAsync(ct);return await GetDetailsAsync(id,ct);}
 public async Task<MbrDetailsResponse?>TransitionAsync(Guid id,TransitionMbrRequest r,CancellationToken ct){var x=await Load(id,ct);if(x is null)return null;await EnsureActor(id,Role(r.Transition),ct);var now=time.GetUtcNow();var qr=await db.QualityRecords.SingleAsync(q=>q.Id==x.QualityRecordId,ct);string type;switch(r.Transition){case"submit-review":x.SubmitReview(r.ExpectedVersion,now);await Complete(id,WorkflowTaskRoles.MbrAuthor,now,ct);type="MbrSubmittedForReview";break;case"review":await signatures.AuthenticateAsync(r.SignaturePassword,r.SignatureMeaningAccepted,ct);x.CompleteReview(r.ExpectedVersion,now);db.Add(Sig(x,"MBR teknik inceleme onayı",now,r.Note,"review"));await Complete(id,WorkflowTaskRoles.MbrReviewer,now,ct);type="MbrReviewed";break;case"approve":await signatures.AuthenticateAsync(r.SignaturePassword,r.SignatureMeaningAccepted,ct);x.Approve(r.ExpectedVersion,now);db.Add(Sig(x,"MBR kalite onayı",now,r.Note,"approve"));type="MbrApproved";break;case"make-effective":await signatures.AuthenticateAsync(r.SignaturePassword,r.SignatureMeaningAccepted,ct);x.MakeEffective(r.ExpectedVersion,r.EffectiveAtUtc?.ToUniversalTime()??now,now);if(x.PreviousVersionId.HasValue){var p=await db.MasterBatchRecords.SingleAsync(y=>y.Id==x.PreviousVersionId,ct);p.Supersede(now);db.Add(Event("MasterBatchRecord",p.Id,p.Version,"MbrSuperseded",now,new{successorId=x.Id}));}qr.Close(now,false);db.Add(Sig(x,"MBR yürürlük ve kontrollü yayın onayı",now,r.Note,"effective"));await CompleteAll(id,now,ct);type="MbrMadeEffective";break;default:throw new ArgumentException("MBR geçişi geçersizdir.");}db.Add(Audit(x,type,now,new{r.Transition,r.EffectiveAtUtc},r.Note));await db.SaveChangesAsync(ct);return await GetDetailsAsync(id,ct);}
 private Task<MasterBatchRecord?>Load(Guid id,CancellationToken ct)=>db.MasterBatchRecords.Include(x=>x.Steps).SingleOrDefaultAsync(x=>x.Id==id,ct);private static IReadOnlyList<MbrTransitionResponse>Transitions(MasterBatchRecordStatus s)=>s switch{MasterBatchRecordStatus.Draft=>[new("submit-review","Teknik incelemeye gönder")],MasterBatchRecordStatus.InReview=>[new("review","Teknik incelemeyi onayla",true)],MasterBatchRecordStatus.Reviewed=>[new("approve","Kalite onayı ver",true)],MasterBatchRecordStatus.Approved=>[new("make-effective","Yürürlüğe al",true)],_=>[]};private static string Role(string t)=>t switch{"submit-review"=>WorkflowTaskRoles.MbrAuthor,"review"=>WorkflowTaskRoles.MbrReviewer,_=>WorkflowTaskRoles.MbrApprover};private async Task<(string,string)>Lookup(string c,string code,CancellationToken ct){var x=await db.MbrLookupDefinitions.AsNoTracking().Where(x=>x.Category==c&&x.Code==code.Trim()&&x.IsActive).Select(x=>new{x.Code,x.Name}).SingleOrDefaultAsync(ct);return x is null?throw new ArgumentException($"{c} etkin M.12 lookup kayıtlarından seçilmelidir."):(x.Code,x.Name);}private async Task<(Guid Id,string Name,Guid?DepartmentId,string?Department)>Resolve(Guid id,string field,CancellationToken ct){var p=await(from u in db.Users.AsNoTracking()join d in db.Departments.AsNoTracking()on u.DepartmentId equals d.Id into ds from d in ds.DefaultIfEmpty()where u.Id==id&&u.IsActive select new{u.Id,u.DisplayName,u.DepartmentId,Department=d==null?null:d.Name}).SingleOrDefaultAsync(ct);return p is null?throw new ArgumentException($"{field} etkin kullanıcı olmalıdır."):(p.Id,p.DisplayName,p.DepartmentId,p.Department);}
 private async Task Assign(Guid id,string role,Guid uid,DateTimeOffset now,CancellationToken ct){var p=await Resolve(uid,"Görev kullanıcısı",ct);db.Add(WorkflowTaskAssignment.Create("MasterBatchRecord",id,role,p.Id,p.DepartmentId,now,assignedUserNameSnapshot:p.Name,assignedDepartmentNameSnapshot:p.Department));db.Add(UserNotification.Create(p.Id,"M.12","Yeni MBR görevi",role==WorkflowTaskRoles.MbrAuthor?"Bir MBR yazarlık görevi size atandı.":role==WorkflowTaskRoles.MbrReviewer?"Bir MBR teknik inceleme görevi size atandı.":"Bir MBR onay görevi size atandı.",$"/modules/m12?open={id}",now));}private async Task EnsureActor(Guid id,string role,CancellationToken ct){if(!await CanAct(id,role,ct))throw new QmsForbiddenException("Bu MBR görevi size veya etkin delegasyonla size atanmamış.");}private async Task<bool>CanAct(Guid id,string role,CancellationToken ct){var ids=await db.WorkflowTaskAssignments.AsNoTracking().Where(t=>t.AggregateType=="MasterBatchRecord"&&t.AggregateId==id&&t.TaskRole==role&&t.Status==WorkflowTaskStatus.Active).Select(t=>t.AssignedUserId).ToListAsync(ct);if(ids.Contains(user.Id))return true;var now=time.GetUtcNow();return ids.Count>0&&await db.Delegations.AsNoTracking().AnyAsync(d=>ids.Contains(d.DelegatorUserId)&&d.DelegateUserId==user.Id&&d.RevokedAtUtc==null&&d.StartsAtUtc<=now&&d.EndsAtUtc>=now&&(d.Scope=="M.12"||d.Scope=="ALL"),ct);}private async Task Complete(Guid id,string role,DateTimeOffset now,CancellationToken ct){foreach(var t in await db.WorkflowTaskAssignments.Where(t=>t.AggregateType=="MasterBatchRecord"&&t.AggregateId==id&&t.TaskRole==role&&t.Status==WorkflowTaskStatus.Active).ToListAsync(ct))t.Complete(now);}private async Task CompleteAll(Guid id,DateTimeOffset now,CancellationToken ct){foreach(var t in await db.WorkflowTaskAssignments.Where(t=>t.AggregateType=="MasterBatchRecord"&&t.AggregateId==id&&t.Status==WorkflowTaskStatus.Active).ToListAsync(ct))t.Complete(now);}
 private ElectronicSignature Sig(MasterBatchRecord x,string meaning,DateTimeOffset now,string?note,string op)=>signatures.CreateInternal(x.QualityRecordId,"MasterBatchRecord",x.Id,x.Version,op,meaning,new{mbr=x,steps=x.Steps,note},now,note);private AuditEvent Audit(MasterBatchRecord x,string type,DateTimeOffset now,object payload,string?reason=null)=>Event("MasterBatchRecord",x.Id,x.Version,type,now,payload,reason);private AuditEvent Event(string aggregate,Guid id,long v,string type,DateTimeOffset now,object payload,string?reason=null)=>AuditEvent.Create(aggregate,id,v,type,user.Id,user.DisplayName,now,Guid.CreateVersion7().ToString(),JsonSerializer.SerializeToDocument(payload),reason);private async Task<long>Next(string type,int year,IDbContextTransaction tx,CancellationToken ct){var c=db.Database.GetDbConnection();if(c.State!=ConnectionState.Open)await c.OpenAsync(ct);await using var cmd=c.CreateCommand();cmd.Transaction=tx.GetDbTransaction();cmd.CommandText="INSERT INTO core.record_number_sequence (\"RecordType\",\"CalendarYear\",\"LastValue\") VALUES (@type,@year,1) ON CONFLICT (\"RecordType\",\"CalendarYear\") DO UPDATE SET \"LastValue\"=core.record_number_sequence.\"LastValue\"+1 RETURNING \"LastValue\";";Add(cmd,"type",type);Add(cmd,"year",year);return Convert.ToInt64(await cmd.ExecuteScalarAsync(ct),CultureInfo.InvariantCulture);}private static void Add(DbCommand c,string n,object v){var p=c.CreateParameter();p.ParameterName=n;p.Value=v;c.Parameters.Add(p);}private sealed class Row{public required MasterBatchRecord Mbr{get;init;}public required string Number{get;init;}}
